    auto rnd=[&]()->float{
        int mode = rng()%6;
        float f;
        switch(mode){
        case 0: { // uniform random bits
            for(;;){ f=fb((uint32_t)rng()); if(ok(f)) return f; }
        }
        case 1: { // wide exponent
            int e = (int)(rng()%260)-130;
            double m = (double)(rng()%2000000)/1000000.0 - 1.0;
